-- PT119-S3-Q11. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT119-S3-Q11$batch11$ AND q.stimulus=$batch11$In early 1990, Queenston instituted a tax increase that gave its school system a larger operating budget. The school system used the larger budget to increase the total number of teachers in the system by 30 percent between 1990 and 1993. Nevertheless, there was no change in the average number of students per teacher between 1990 and 1993.$batch11$ AND q.prompt=$batch11$If the statements above are true, then on the basis of them which one of the following must also be true?$batch11$ AND q.correct_choice=$batch11$B$batch11$) THEN RAISE EXCEPTION 'Question changed: PT119-S3-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT119-S3-Q11$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S3-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT119-S3-Q11$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Queenston added 30 percent more teachers between 1990 and 1993. The average number of students per teacher didn't change.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Students per teacher is students divided by teachers. If teachers went up 30 percent and the ratio stayed flat, students must also have gone up, by 30 percent.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Total enrollment increased.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT119-S3-Q11$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$The average is flat, but individual classes could have grown while others shrank.$batch11$), ($batch11$B$batch11$, $batch11$More teachers with the same ratio means more students.$batch11$), ($batch11$C$batch11$, $batch11$The budget got larger. We don't know by how much, and teachers aren't the only cost.$batch11$), ($batch11$D$batch11$, $batch11$Teacher turnover never comes up. The count grew, but the people could have changed.$batch11$), ($batch11$E$batch11$, $batch11$Quality of education never comes up, and the student-teacher ratio didn't even improve.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT119-S3-Q11$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
